import {ROOMS,TYPES,uid,norm,roomName,initialState,cleanState,setDevice,runScene,executeCommand,evaluateRules,energy,power,log} from './model.js';
import {icon as I} from './icons.js';
import {HouseView} from './house.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='jm-home-pro-r02';let state=initialState(),storageOK=true,view=null,room='all',typeFilter='all',search='',camera=null;
try{const saved=localStorage.getItem(KEY);if(saved)state=cleanState(JSON.parse(saved));}catch{storageOK=false;}
const pages={inicio:['Visão geral','grid'],casa:['Casa 3D','cube'],dispositivos:['Dispositivos','bulb'],cenas:['Cenas e rotinas','clock'],energia:['Energia','bolt'],assistente:['Assistente','spark'],integracoes:['Integrações','plug'],configuracoes:['Configurações','settings']};
let route=pages[location.hash.slice(1)]?location.hash.slice(1):'inicio';
const fmt=(n,d=1)=>Number(n).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}),money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Armazenamento indisponível. Exporte sua configuração antes de sair.','warning');}}
let toastTimer;function toast(message,status='ok'){const el=$('#toast');el.className=`show ${status}`;el.innerHTML=`${I(status==='ok'?'check':'info')}<span>${E(message)}</span>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',5000);}
function header(title,subtitle,button=''){return `<div class="page-heading"><div><p class="eyebrow">SEU ESPAÇO. SUAS REGRAS.</p><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`;}
const btn=(act,label,icon='plus',cls='primary',extra='')=>`<button class="btn ${cls}" data-act="${act}" ${extra}>${I(icon)}${label}</button>`;
const pill=(label,cls='')=>`<span class="pill ${cls}">${label}</span>`;
function nav(){return Object.entries(pages).map(([key,[name,icon]],index)=>`${index===6?'<p class="nav-label">SISTEMA</p>':''}<a href="#${key}" class="nav-link ${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${I(icon)}<span>${name}</span>${key==='assistente'?'<small>LOCAL</small>':''}</a>`).join('');}
function shell(){return `<aside class="sidebar"><a class="brand" href="#inicio"><img src="./assets/icon.svg" alt=""><span>JM<span class="brand-light"> HOME</span><small>SMART LIVING</small></span><b>PRO</b></a><button class="home-select" data-act="home-settings">${I('home')}<span><small>MEU AMBIENTE</small><strong>${E(state.settings.home)}</strong></span>${I('down')}</button><p class="nav-label">PRINCIPAL</p><nav aria-label="Navegação principal">${nav()}</nav><div class="sidebar-bottom"><div class="local-card"><span class="status-dot"></span><strong>Seu espaço conectado</strong><small>Ambiente de demonstração</small><div class="tiny-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><button class="profile" data-act="home-settings"><span class="avatar">JM</span><span><strong>${E(state.settings.owner)}</strong><small>Administrador local</small></span>${I('settings')}</button></div></aside><div class="workspace"><header class="topbar"><button class="icon-button menu-toggle" data-act="menu" aria-label="Abrir menu">${I('menu')}</button><div class="breadcrumb">Painel ${I('chevron')} <strong>${pages[route][0]}</strong></div><div class="top-actions"><span class="demo-dot"></span><span class="demo-label">Modo demonstração</span><button class="icon-button" data-act="history" aria-label="Ver histórico">${I('bell')}<i></i></button><span class="avatar small">JM</span></div></header><main id="conteudo" tabindex="-1">${renderPage()}</main><footer><span><b>JM HOME PRO</b> <em>·</em> Inteligência para o seu espaço.</span><span>R02 <em>·</em> Dados salvos ${storageOK?'neste navegador':'apenas nesta sessão'}</span></footer></div><button class="mobile-shade" data-act="menu" aria-label="Fechar menu"></button>`;}
function render(){if(view){camera={yaw:view.yaw,pitch:view.pitch,zoom:view.zoom};view.destroy();view=null;}$('#app').innerHTML=shell();document.title=`${pages[route][0]} · JM HOME PRO`;const canvas=$('#house');if(canvas){view=new HouseView(canvas,()=>state,id=>{room=id;if(route==='casa')render();else go('casa');},id=>mutate(setDevice(state,id,{on:!state.devices.find(d=>d.id===id).on},'Mapa 3D')));if(camera){Object.assign(view,camera);view.draw();}view.setRoom(room);}const chat=$('#chat-messages');if(chat)chat.scrollTop=chat.scrollHeight;}
function go(to){if(route===to)return;location.hash=to;}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next==='conteudo'){$('#conteudo').focus();return;}route=pages[next]?next:'inicio';render();window.scrollTo(0,0);});
function mutate(result,rerender=true){save();if(rerender)render();toast(result.message,result.ok?'ok':'warning');}
function sceneCards(compact=false){return state.scenes.map(c=>`<article class="scene-card ${c.color} ${state.activeScene===c.id?'selected':''}"><button class="scene-run" data-act="scene" data-id="${E(c.id)}" aria-label="Ativar cena ${E(c.name)}"><span class="scene-icon">${I(c.icon)}</span><strong>${E(c.name)}</strong>${!compact?`<p>${E(c.description||`${c.actions.length} ações configuradas`)}</p>`:''}<span class="scene-play">${I(state.activeScene===c.id?'check':'play')}</span></button>${!compact?`<div class="scene-footer"><small>${c.actions.length} ações ${state.activeScene===c.id?'· última ativada':''}</small><button class="icon-button" data-act="edit-scene" data-id="${E(c.id)}" aria-label="Editar cena ${E(c.name)}">${I('edit')}</button></div>`:''}</article>`).join('')||'<p class="empty">Crie sua primeira cena.</p>';}
function mapPanel(full=false){return `<section class="panel map-panel"><div class="panel-heading"><div><span class="kicker">SUA CASA EM TEMPO DE DEMONSTRAÇÃO</span><h2>${full?'Explore cada ambiente':'Tudo conectado. Tudo sob controle.'}</h2></div>${pill(`${ROOMS.length} ambientes`,'subtle')}</div><div class="map-stage ${full?'large':''}"><canvas id="house" role="img" aria-label="Casa 3D interativa: arraste para girar, use as setas do teclado para orientar e os botões de luz para controlar. Os controles equivalentes estão na lista de dispositivos." tabindex="0"></canvas><div class="map-top"><span class="live-badge"><i></i> CASA MODELO</span><div class="view-modes"><button data-act="3d" aria-label="Vista em três dimensões">3D</button><button data-act="plan">Planta</button></div></div><div class="map-tools">${['plus','minus','refresh'].map((i,n)=>`<button class="icon-button" data-act="${['zoom-in','zoom-out','reset-view'][n]}" aria-label="${['Aproximar','Afastar','Restaurar vista'][n]}">${I(i)}</button>`).join('')}</div><span class="map-hint">${I('cube')} Arraste para explorar <span>· Toque nas luzes</span></span>${!full?'<a class="map-link" href="#casa">Abrir casa 3D '+I('arrow')+'</a>':''}</div><div class="map-bottom"><span><i class="dot violet"></i> Dispositivo ligado</span><span><i class="dot gray"></i> Desligado</span><small>Modelo ilustrativo · Sem escala de projeto</small></div></section>`;}
function overview(){const e=energy(state),active=state.devices.filter(d=>d.on&&d.online).length,available=state.devices.filter(d=>d.online).length;return `${header(`Bem-vindo, ${E(state.settings.owner)} <span class="greeting-spark">✦</span>`,'Uma casa mais inteligente. Uma rotina mais leve.',btn('new-device','Adicionar dispositivo'))}<div class="stats-grid">${[[I('plug'),available,'Dispositivos disponíveis',`${state.devices.length} cadastrados`,'purple'],[I('bulb'),active,'Dispositivos em uso','Estados simulados','amber'],[I('bolt'),`${fmt(e.watts/1000,2)} <small>kW</small>`,'Potência estimada agora','Baseada nas cargas cadastradas','green'],[I('clock'),state.rules.filter(r=>r.enabled).length,'Rotinas ativas',`${state.scenes.length} cenas prontas`,'blue']].map(([ico,value,label,sub,color])=>`<article class="stat"><span class="stat-icon ${color}">${ico}</span><small>${label}</small><strong>${value}</strong><span>${sub}</span></article>`).join('')}</div><div class="dashboard-grid"><div class="dashboard-main">${mapPanel()}<section class="panel scenes-strip"><div class="section-heading"><h2>Um toque. Seu momento.</h2><a href="#cenas">Todas as cenas ${I('arrow')}</a></div><div class="scenes-grid compact">${sceneCards(true)}</div></section></div><aside class="dashboard-right"><section class="assistant-teaser"><div class="teaser-header">${pill('ASSISTENTE LOCAL')}<span class="mini-stars">✧</span></div><div class="orb"><div></div><i></i></div><h2>Sua casa.<br>Sua voz. Seu controle.</h2><p>Peça, ajuste e crie o clima<br>ideal para cada momento.</p><button class="assistant-input" data-act="assistant">“Ativar modo cinema” ${I('arrow')}</button><span class="teaser-note">Comandos predefinidos · Sem IA generativa</span></section><section class="panel energy-mini"><div class="section-heading"><h2>${I('leaf')} Consumo planejado</h2><a href="#energia" aria-label="Abrir planejamento de energia">${I('arrow')}</a></div><strong>${fmt(e.kwh)} <small>kWh/mês</small></strong><div class="progress"><span style="width:${Math.min(100,e.kwh/Math.max(1,state.settings.budget)*100)}%"></span></div><p>${state.settings.budget>0?`${fmt(e.kwh/state.settings.budget*100,0)}% da meta de ${fmt(state.settings.budget,0)} kWh/mês`:'Defina uma meta na aba Energia'}</p><span class="estimate-note">Projeção por potência × horas de uso.</span></section><section class="panel mini-sensors"><span>${I('thermo')} <b>${fmt(state.sensors.temperature,0)}°</b> Temperatura</span><span>${I('drop')} <b>${fmt(state.sensors.humidity,0)}%</b> Umidade</span><small>Sensores simulados <a href="#cenas">Ajustar</a></small></section></aside></div><div class="demo-notice">${I('info')} Explore à vontade: os dispositivos e sensores são simulados. Nenhum equipamento real está conectado.</div>`;}
function roomTabs(){return `<div class="room-tabs" role="group" aria-label="Filtrar ambiente"><button data-act="room" data-id="all" class="${room==='all'?'active':''}" aria-pressed="${room==='all'}">${I('grid')} Todos os ambientes</button>${ROOMS.map(r=>`<button data-act="room" data-id="${r.id}" class="${room===r.id?'active':''}" aria-pressed="${room===r.id}">${I(r.icon)}${r.name}</button>`).join('')}</div>`;}
function deviceCard(d){const active=d.on&&d.online;return `<article class="device-card ${active?'on':''} ${!d.online?'offline':''}"><div class="device-top"><span class="device-icon">${I(TYPES[d.type].icon)}</span><button role="switch" aria-checked="${active}" aria-label="Ligar ou desligar ${E(d.name)}" class="switch ${active?'on':''}" data-act="toggle" data-id="${E(d.id)}" ${!d.online?'disabled':''}><span></span></button></div><small>${E(roomName(d.room))}</small><h3>${E(d.name)}</h3><div class="device-state"><i class="status-dot ${active?'':'off'}"></i>${!d.online?'Desconectado':d.type==='curtain'?`${d.level}% aberta`:d.on?d.type==='ac'?`${d.temp} °C`:'Ligado':'Desligado'}<span>${d.type==='curtain'?'Posição simulada':`${fmt(power(d),0)} W estimados`}</span></div>${['light','curtain','fan'].includes(d.type)?`<div class="range-wrap"><label for="level-${E(d.id)}">${d.type==='curtain'?'Abertura':d.type==='fan'?'Velocidade':'Intensidade'} <output>${d.level}%</output></label><input id="level-${E(d.id)}" data-control="level" data-id="${E(d.id)}" type="range" min="0" max="100" step="5" value="${d.level}" ${!d.online?'disabled':''}></div>`:d.type==='ac'?`<div class="temperature"><button data-act="temp-down" data-id="${E(d.id)}" aria-label="Diminuir temperatura de ${E(d.name)}" ${!d.online||d.temp<=16?'disabled':''}>${I('minus')}</button><strong>${d.temp}<small> °C</small></strong><button data-act="temp-up" data-id="${E(d.id)}" aria-label="Aumentar temperatura de ${E(d.name)}" ${!d.online||d.temp>=30?'disabled':''}>${I('plus')}</button></div>`:`<div class="device-filler">${I('shield')} Controle local de demonstração</div>`}<button class="device-edit" data-act="edit-device" data-id="${E(d.id)}">Configurar ${I('sliders')}</button></article>`;}
function devices(){const list=state.devices.filter(d=>(room==='all'||d.room===room)&&(typeFilter==='all'||d.type===typeFilter)&&norm(`${d.name} ${roomName(d.room)}`).includes(norm(search)));return `${header('Dispositivos','Cada conexão, no lugar certo.',btn('new-device','Novo dispositivo'))}${roomTabs()}<div class="filter-row"><label class="search-box">${I('search')}<input id="device-search" type="search" value="${E(search)}" placeholder="Buscar dispositivo ou ambiente" aria-label="Buscar dispositivos"></label><select id="type-filter" aria-label="Filtrar tipo de dispositivo"><option value="all">Todos os tipos</option>${Object.entries(TYPES).map(([k,t])=>`<option value="${k}" ${k===typeFilter?'selected':''}>${t.name}</option>`).join('')}</select><span>${list.length} dispositivo(s)</span></div><div class="devices-grid" id="device-grid">${list.map(deviceCard).join('')||'<div class="empty">Nenhum dispositivo encontrado. Altere os filtros ou adicione um novo.</div>'}</div>`;}
function house(){const list=state.devices.filter(d=>room==='all'||d.room===room);return `${header('Seu espaço, em outra dimensão.','Explore a casa, escolha um ambiente e controle os dispositivos.',btn('new-device','Adicionar dispositivo'))}${roomTabs()}${mapPanel(true)}<div class="section-heading space-top"><h2>${room==='all'?'Dispositivos da casa':roomName(room)}</h2><a href="#dispositivos">Gerenciar dispositivos ${I('arrow')}</a></div><div class="devices-grid">${list.map(deviceCard).join('')||'<div class="empty">Sem dispositivos neste ambiente.</div>'}</div>`;}
function scenes(){return `${header('A casa acompanha seu ritmo.','Crie momentos e automatize os detalhes da sua rotina.',btn('new-scene','Criar cena','spark'))}<div class="section-heading"><h2>Suas cenas</h2><span class="muted">Ações agrupadas em um toque</span></div><div class="scenes-grid">${sceneCards()}</div><div class="section-heading space-top"><h2>Automações</h2>${btn('new-rule','Nova rotina','plus','secondary')}</div><div class="notice">${I('clock')} As rotinas executam enquanto esta página estiver aberta e ativa. Horários usam o fuso do seu navegador. Condições de sensores disparam ao cruzar o limite; horários perdidos não são recuperados.</div><div class="rules-list">${state.rules.map(r=>`<article class="rule-card"><span class="rule-icon">${I(r.kind==='time'?'clock':'thermo')}</span><div><h3>${E(r.name)}</h3><p>${r.kind==='time'?`Todos os dias, às ${r.time}`:`${{temperature:'Temperatura',humidity:'Umidade',illuminance:'Luminosidade'}[r.sensor]} ${r.operator==='gt'?'acima':'abaixo'} de ${r.threshold} ${{temperature:'°C',humidity:'%',illuminance:'lx'}[r.sensor]}`} ${I('arrow')} ${E(state.scenes.find(c=>c.id===r.scene)?.name??'Cena removida')}</p></div><button class="switch ${r.enabled?'on':''}" role="switch" aria-label="Ativar rotina ${E(r.name)}" aria-checked="${r.enabled}" data-act="toggle-rule" data-id="${E(r.id)}"><span></span></button><button class="icon-button" data-act="edit-rule" data-id="${E(r.id)}" aria-label="Editar rotina ${E(r.name)}">${I('edit')}</button></article>`).join('')||'<p class="empty">Nenhuma rotina. Crie uma por horário ou condição.</p>'}</div><section class="panel sensor-lab"><div><span class="kicker">LABORATÓRIO DE AUTOMAÇÃO</span><h2>Simule. Observe. Ajuste.</h2><p>Altere um sensor para testar suas rotinas por condição.</p></div><div class="sensor-controls">${[['temperature','Temperatura','°C',-10,60],['humidity','Umidade','%',0,100],['illuminance','Luminosidade','lx',0,2000]].map(([id,name,u,min,max])=>`<label>${name}<strong><output>${state.sensors[id]}</output> ${u}</strong><input type="range" data-sensor="${id}" min="${min}" max="${max}" value="${state.sensors[id]}" step="${id==='illuminance'?10:1}" aria-label="${name} simulada"></label>`).join('')}</div></section>`;}
function energyPage(){const e=energy(state),max=Math.max(1,...e.devices.map(d=>d.kwh));return `${header('Energia com mais consciência.','Planeje o uso dos equipamentos e compare o impacto de cada carga.',btn('export-energy','Exportar CSV','download','secondary'))}<div class="notice">${I('info')} Estimativa de engenharia simplificada: kWh/mês = potência nominal em W × horas/dia × 30 ÷ 1.000. Não considera ciclo de compressores, standby, impostos adicionais nem variação real da carga. Cortinas não entram no cálculo.</div><div class="energy-stats stats-grid"><article class="stat"><span class="stat-icon green">${I('bolt')}</span><small>Projeção mensal</small><strong>${fmt(e.kwh)} <small>kWh</small></strong><span>Uso configurado · 30 dias</span></article><article class="stat"><span class="stat-icon purple">${I('chart')}</span><small>Custo projetado</small><strong>${money(e.cost)}</strong><span>Tarifa: ${money(state.settings.tariff)}/kWh</span></article><article class="stat"><span class="stat-icon amber">${I('bulb')}</span><small>Potência estimada agora</small><strong>${fmt(e.watts,0)} <small>W</small></strong><span>Dispositivos simulados em uso</span></article><article class="stat"><span class="stat-icon blue">${I('leaf')}</span><small>Meta de consumo</small><strong>${fmt(state.settings.budget,0)} <small>kWh</small></strong><span>${state.settings.budget?e.kwh>state.settings.budget?'Projeção acima da meta':'Projeção dentro da meta':'Sem meta configurada'}</span></article></div><div class="energy-layout"><section class="panel energy-table"><div class="section-heading"><h2>Planejamento por dispositivo</h2><span class="muted">Valores editáveis</span></div><div class="table-wrap"><table><thead><tr><th>Dispositivo</th><th>Potência (W)</th><th>Uso (h/dia)</th><th>kWh/mês</th><th>R$/mês</th></tr></thead><tbody>${state.devices.filter(d=>d.type!=='curtain').map(d=>{const k=d.watts*d.hours*.03;return `<tr><td><strong>${E(d.name)}</strong><small>${E(roomName(d.room))}</small></td><td><input class="number-input" type="number" min="0" max="30000" step="1" data-energy="watts" data-id="${E(d.id)}" value="${d.watts}" aria-label="Potência de ${E(d.name)}"></td><td><input class="number-input" type="number" min="0" max="24" step=".1" data-energy="hours" data-id="${E(d.id)}" value="${d.hours}" aria-label="Horas de uso de ${E(d.name)}"></td><td>${fmt(k)}</td><td>${money(k*state.settings.tariff)}</td></tr>`;}).join('')}</tbody></table></div></section><aside><section class="panel energy-config"><h2>Seu cenário</h2><form data-form="energy"><label>Tarifa de energia (R$/kWh)<input name="tariff" type="number" min="0" max="10" step=".01" required value="${state.settings.tariff}"></label><label>Meta mensal (kWh)<input name="budget" type="number" min="0" max="100000" step="1" required value="${state.settings.budget}"></label><button class="btn primary" type="submit">${I('check')} Aplicar cenário</button></form><p>Consulte a tarifa da sua fatura. Os valores iniciais são apenas exemplos.</p></section><section class="panel ranking"><h2>Maiores participações</h2>${[...e.devices].sort((a,b)=>b.kwh-a.kwh).slice(0,5).map(d=>`<div><span>${E(d.name)}<b>${fmt(d.kwh)} kWh</b></span><div class="progress"><span style="width:${d.kwh/max*100}%"></span></div></div>`).join('')}</section></aside></div>`;}
function chatMessages(){return `<div class="message assistant"><span class="chat-avatar">${I('spark')}</span><div><strong>Assistente JM</strong><p>Olá! Seu espaço está pronto. Posso ajustar dispositivos, ativar cenas e consultar a projeção de energia. Como posso ajudar?</p></div></div>${state.messages.map(m=>`<div class="message ${m.role}"><span class="chat-avatar">${m.role==='user'?'JM':I('spark')}</span><div><strong>${m.role==='user'?'Você':'Assistente JM'}</strong><p>${E(m.text)}</p></div></div>`).join('')}`;}
function assistant(){return `${header('Uma conversa. Muitas possibilidades.','Comandos simples para transformar seu ambiente.',btn('clear-chat','Limpar conversa','trash','secondary'))}<div class="assistant-layout"><section class="panel chat-panel"><div class="chat-heading"><span class="assistant-mark">${I('spark')}</span><div><h2>Assistente JM</h2><small><i class="status-dot"></i> Processamento local de comandos</small></div>${pill('DEMO','subtle')}</div><div class="chat-messages" id="chat-messages" role="log" aria-live="polite">${chatMessages()}</div><div class="suggestions">${['Ligar luzes da sala','Cinema','Ar da sala em 23 graus','Desligar tudo','Consumo de energia'].map(q=>`<button data-act="suggest" data-command="${q}">${q}</button>`).join('')}</div><form class="chat-form" data-form="chat"><input name="command" required maxlength="300" placeholder="O que vamos fazer agora?" aria-label="Digite um comando" autocomplete="off"><button type="button" class="icon-button" data-act="voice" aria-label="Ditar comando">${I('mic')}</button><button type="submit" class="send" aria-label="Enviar comando">${I('arrow')}</button></form><p class="chat-disclaimer">Comandos predefinidos. Sem IA generativa. A voz depende do navegador e pode usar o serviço de reconhecimento dele.</p></section><aside class="assistant-guide"><div class="orb small-orb"><div></div><i></i></div><h2>O que posso fazer?</h2><article>${I('bulb')}<div><strong>Ajustar o ambiente</strong><p>“Luzes da sala em 30%”<br>“Abrir cortina da sala”</p></div></article><article>${I('spark')}<div><strong>Criar o momento</strong><p>Ative qualquer cena pelo nome.<br>Exemplo: “Boa noite”</p></div></article><article>${I('bolt')}<div><strong>Entender o consumo</strong><p>“Consumo de energia”<br>“Status da casa”</p></div></article><div class="notice">${I('shield')} Comandos não reconhecidos não alteram dispositivos.</div></aside></div>`;}
function integrations(){return `${header('Um painel. Novas possibilidades.','Caminhos de integração para evoluir do protótipo ao equipamento real.')}<div class="notice">${I('info')} Esta versão funciona localmente com dados simulados. As conexões abaixo ainda não estão implementadas; nenhum token ou senha é solicitado.</div><div class="integration-grid">${[['ha','Home Assistant','home','Um ponto central para estados, serviços e eventos dos equipamentos.'],['mqtt','MQTT / ESP32','code','Seu hardware, seus sensores e seus comandos em uma arquitetura própria.'],['tuya','Tuya / Smart Life','plug','Integração futura por serviços e dispositivos compatíveis.'],['meter','Medição de energia','bolt','Substitua as estimativas por dados de um medidor compatível.']].map(([id,title,ico,desc])=>`<section class="panel integration"><span class="integration-icon">${I(ico)}</span>${pill('NÃO CONECTADO','subtle')}<h2>${title}</h2><p>${desc}</p><button class="btn secondary" data-act="integration" data-id="${id}">Ver requisitos ${I('arrow')}</button></section>`).join('')}</div><section class="panel architecture"><h2>Uma base preparada para crescer</h2><div><span>${I('cube')} Interface e casa 3D</span>${I('arrow')}<span>${I('shield')} Backend autenticado<br><small>A implementar</small></span>${I('arrow')}<span>${I('plug')} Adaptador de integração<br><small>A implementar</small></span>${I('arrow')}<span>${I('home')} Equipamentos reais<br><small>A conectar</small></span></div><p>A integração real exigirá autenticação, permissões, retorno confirmado do estado e tratamento de falhas. O painel atual nunca envia comandos aos seus equipamentos.</p></section>`;}
function settings(){return `${header('Do seu jeito.','Personalize seu espaço e mantenha uma cópia das configurações.')}<div class="settings-layout"><section class="panel settings-form"><h2>Identidade do ambiente</h2><form data-form="settings"><label>Nome do ambiente<input name="home" value="${E(state.settings.home)}" maxlength="40" required></label><label>Como você quer ser chamado<input name="owner" value="${E(state.settings.owner)}" maxlength="40" required></label><label class="checkbox-row"><input name="voice" type="checkbox" ${state.settings.voice?'checked':''}>Ler as respostas do assistente em voz alta</label><button class="btn primary" type="submit">${I('check')} Salvar preferências</button></form></section><section class="panel backup-panel"><h2>Seu projeto, com você.</h2><p>Exporte dispositivos, cenas, rotinas, histórico e configurações em JSON. Importe para restaurar em outro navegador.</p><div>${btn('export','Exportar projeto','download','secondary')}${btn('import','Importar projeto','upload','secondary')}</div><small>Importar substitui a configuração atual após confirmação.</small><hr><h3>Dados locais</h3><p>Os dados ficam neste navegador. Não há sincronização entre aparelhos, contas compartilhadas ou serviço de automação em segundo plano.</p><button class="text-danger" data-act="reset">Restaurar demonstração inicial</button></section></div><section class="panel about"><img src="./assets/icon.svg" alt=""><div><h2>JM HOME PRO <span>R02</span></h2><p>Implementação própria para exploração de automação residencial. Visual inspirado na referência apresentada. O modelo de casa é ilustrativo e não substitui uma planta técnica.</p></div></section>`;}
function renderPage(){return({inicio:overview,casa:house,dispositivos:devices,cenas:scenes,energia:energyPage,assistente:assistant,integracoes:integrations,configuracoes:settings})[route]();}
function modal(title,content,wide=false){const d=$('#modal');d.innerHTML=`<div class="modal-heading"><h2>${title}</h2><button class="icon-button" data-act="close-modal" aria-label="Fechar janela">${I('close')}</button></div>${content}`;d.className=wide?'wide':'';if(!d.open)d.showModal();}
function close(){$('#modal').close();}
function deviceDialog(id){const d=state.devices.find(d=>d.id===id)??{id:'',name:'',room:room==='all'?'sala':room,type:'light',watts:12,hours:4,online:true};modal(d.id?'Configurar dispositivo':'Novo dispositivo',`<p class="modal-sub">Dispositivo de demonstração. Nenhum pareamento real será realizado.</p><form data-form="device" data-id="${E(d.id)}"><label>Nome<input name="name" maxlength="60" required value="${E(d.name)}" placeholder="Ex.: Luminária da sala"></label><div class="form-grid"><label>Ambiente<select name="room">${ROOMS.map(r=>`<option value="${r.id}" ${r.id===d.room?'selected':''}>${r.name}</option>`).join('')}</select></label><label>Tipo<select name="type" ${d.id?'disabled':''}>${Object.entries(TYPES).map(([k,t])=>`<option value="${k}" ${k===d.type?'selected':''}>${t.name}</option>`).join('')}</select></label><label>Potência nominal (W)<input type="number" name="watts" min="0" max="30000" required step="1" value="${d.watts}"></label><label>Uso estimado (h/dia)<input type="number" name="hours" min="0" max="24" step=".1" required value="${d.hours}"></label></div><label class="checkbox-row"><input name="online" type="checkbox" ${d.online?'checked':''}>Disponível (desmarque para simular desconexão)</label><div class="form-actions">${d.id?`<button class="text-danger" type="button" data-act="delete-device" data-id="${E(d.id)}">Excluir dispositivo</button>`:'<span></span>'}<button class="btn primary" type="submit">${I('check')} Salvar dispositivo</button></div></form>`);}
function sceneDialog(id){const c=state.scenes.find(c=>c.id===id);modal(c?'Editar cena':'Criar uma cena',`<p class="modal-sub">Selecione os dispositivos e o estado desejado para cada um.</p><form data-form="scene" data-id="${E(id??'')}"><div class="form-grid"><label>Nome da cena<input name="name" maxlength="50" required value="${E(c?.name??'')}" placeholder="Ex.: Estudar"></label><label>Ícone<select name="icon">${[['spark','Personalizada'],['sun','Dia'],['moon','Noite'],['film','Cinema'],['exit','Saída']].map(([k,v])=>`<option value="${k}" ${c?.icon===k?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Descrição<input name="description" maxlength="150" value="${E(c?.description??'')}" placeholder="O que essa cena prepara?"></label><div class="scene-actions-editor">${state.devices.map(d=>{const a=c?.actions.find(a=>a.device===d.id);return `<div class="action-editor" data-device="${E(d.id)}"><label class="checkbox-row"><input type="checkbox" name="include" ${a?'checked':''}><span><strong>${E(d.name)}</strong><small>${roomName(d.room)}</small></span></label><label class="checkbox-row desired"><input type="checkbox" name="on" ${(a?a.on:d.on)?'checked':''}>${d.type==='curtain'?'Abrir':'Ligar'}</label>${['light','curtain','fan','ac'].includes(d.type)?`<label class="action-level">${d.type==='ac'?'°C':'%'}<input type="number" name="value" min="${d.type==='ac'?16:0}" max="${d.type==='ac'?30:100}" value="${d.type==='ac'?(a?.temp??d.temp):(a?.level??d.level)}" required></label>`:''}</div>`;}).join('')}</div><div class="form-actions">${c?`<button type="button" class="text-danger" data-act="delete-scene" data-id="${E(c.id)}">Excluir cena</button>`:'<small>Até 30 cenas</small>'}<button class="btn primary" type="submit">${I('check')} Salvar cena</button></div></form>`,true);}
function ruleDialog(id){if(!state.scenes.length){toast('Crie uma cena antes de adicionar uma rotina.','warning');return;}const r=state.rules.find(r=>r.id===id)??{id:'',name:'',kind:'time',time:'22:00',sensor:'temperature',operator:'gt',threshold:28,scene:state.scenes[0].id,enabled:false};modal(r.id?'Editar rotina':'Nova rotina',`<p class="modal-sub">Executada apenas com a página aberta e ativa.</p><form data-form="rule" data-id="${E(r.id)}"><label>Nome<input name="name" required maxlength="60" value="${E(r.name)}" placeholder="Ex.: Climatizar sala"></label><label>Quando<select name="kind" id="rule-kind"><option value="time" ${r.kind==='time'?'selected':''}>Chegar um horário</option><option value="sensor" ${r.kind==='sensor'?'selected':''}>Um sensor cruzar um limite</option></select></label><div id="rule-time" ${r.kind!=='time'?'hidden':''}><label>Todos os dias às<input name="time" type="time" required value="${r.time}"></label></div><div id="rule-sensor" ${r.kind!=='sensor'?'hidden':''}><div class="form-grid"><label>Sensor<select name="sensor">${[['temperature','Temperatura (°C)'],['humidity','Umidade (%)'],['illuminance','Luminosidade (lx)']].map(([k,n])=>`<option value="${k}" ${r.sensor===k?'selected':''}>${n}</option>`).join('')}</select></label><label>Condição<select name="operator"><option value="gt" ${r.operator==='gt'?'selected':''}>Acima de</option><option value="lt" ${r.operator==='lt'?'selected':''}>Abaixo de</option></select></label></div><label>Limite<input name="threshold" type="number" min="-50" max="100000" step=".1" required value="${r.threshold}"></label></div><label>Executar cena<select name="scene">${state.scenes.map(c=>`<option value="${E(c.id)}" ${r.scene===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select></label><label class="checkbox-row"><input name="enabled" type="checkbox" ${r.enabled?'checked':''}>Ativar rotina ao salvar</label><div class="form-actions">${r.id?`<button type="button" class="text-danger" data-act="delete-rule" data-id="${E(r.id)}">Excluir rotina</button>`:'<span></span>'}<button class="btn primary" type="submit">${I('check')} Salvar rotina</button></div></form>`);}
function confirm(title,message,action,id=''){modal(title,`<p class="modal-sub">${E(message)}</p><div class="form-actions"><button class="btn secondary" data-act="close-modal">Cancelar</button><button class="btn primary" data-act="${action}" data-id="${E(id)}">Confirmar</button></div>`);}
function download(name,data,mime){const url=URL.createObjectURL(new Blob([data],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function command(text){state.messages.push({role:'user',text});const result=executeCommand(state,text);state.messages.push({role:'assistant',text:result.message});state.messages=state.messages.slice(-30);save();render();if(state.settings.voice&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(result.message);u.lang='pt-BR';speechSynthesis.speak(u);}}
let pendingImport=null;
document.addEventListener('click',e=>{if(e.target.closest('a[href^="#"]'))document.body.classList.remove('menu-open');const el=e.target.closest('[data-act]');if(!el)return;const a=el.dataset.act,id=el.dataset.id,d=state.devices.find(d=>d.id===id);if(a==='close-modal'){close();return;}
 if(a==='menu'){$('body').classList.toggle('menu-open');return;}
 if(a==='room'){room=id;render();return;}
 if(a==='home-settings'){go('configuracoes');return;}
 if(a==='assistant'){go('assistente');return;}
 if(a==='toggle'){mutate(setDevice(state,id,{on:!d.on}));return;}
 if(a==='temp-up'||a==='temp-down'){mutate(setDevice(state,id,{temp:d.temp+(a==='temp-up'?1:-1)}));return;}
 if(a==='scene'){mutate(runScene(state,id));return;}
 if(a==='new-device'||a==='edit-device'){if(a==='new-device'&&state.devices.length>=100){toast('Limite de 100 dispositivos alcançado.','warning');return;}deviceDialog(id);return;}
 if(a==='new-scene'||a==='edit-scene'){if(a==='new-scene'&&state.scenes.length>=30){toast('Limite de 30 cenas alcançado.','warning');return;}sceneDialog(id);return;}
 if(a==='new-rule'||a==='edit-rule'){if(a==='new-rule'&&state.rules.length>=50){toast('Limite de 50 rotinas alcançado.','warning');return;}ruleDialog(id);return;}
 if(a==='toggle-rule'){const r=state.rules.find(r=>r.id===id);r.enabled=!r.enabled;r.latched=false;log(state,`${r.name}: ${r.enabled?'ativada':'pausada'}.`,'Rotinas');save();render();return;}
 if(a==='zoom-in')view?.zoomBy(.1);if(a==='zoom-out')view?.zoomBy(-.1);if(a==='reset-view'||a==='3d')view?.reset();if(a==='plan')view?.top();
 if(a==='suggest')command(el.dataset.command);
 if(a==='history')modal('Histórico de atividades',`<p class="modal-sub">Últimos 100 eventos deste navegador.</p><div class="history">${state.history.map(h=>`<article><span class="history-icon">${I(h.status==='warning'?'info':'check')}</span><div><strong>${E(h.message)}</strong><small>${E(h.source)} · ${new Date(h.at).toLocaleString('pt-BR')}</small></div></article>`).join('')||'<div class="empty">Ainda sem eventos. Experimente uma cena ou controle um dispositivo.</div>'}</div>`);
 if(a==='delete-device')confirm('Excluir dispositivo?', 'Ele será removido também das ações das cenas. Faça uma exportação se quiser preservar a configuração.','confirm-delete-device',id);
 if(a==='confirm-delete-device'){state.devices=state.devices.filter(d=>d.id!==id);state.scenes.forEach(c=>c.actions=c.actions.filter(a=>a.device!==id));close();mutate({ok:true,message:'Dispositivo removido.'});}
 if(a==='delete-scene')confirm('Excluir cena?','As rotinas que dependem desta cena também serão removidas.','confirm-delete-scene',id);
 if(a==='confirm-delete-scene'){state.scenes=state.scenes.filter(c=>c.id!==id);state.rules=state.rules.filter(r=>r.scene!==id);if(state.activeScene===id)state.activeScene=null;close();mutate({ok:true,message:'Cena removida.'});}
 if(a==='delete-rule')confirm('Excluir rotina?','Essa automação deixará de existir na configuração local.','confirm-delete-rule',id);
 if(a==='confirm-delete-rule'){state.rules=state.rules.filter(r=>r.id!==id);close();mutate({ok:true,message:'Rotina removida.'});}
 if(a==='export')download('JM_HOME_PRO_R02.json',JSON.stringify(state,null,2),'application/json');
 if(a==='import')$('#import-file').click();
 if(a==='confirm-import'){state=pendingImport;pendingImport=null;room='all';close();mutate({ok:true,message:'Projeto importado e validado.'});}
 if(a==='reset')confirm('Restaurar demonstração?','Dispositivos, cenas, rotinas e mensagens locais serão substituídos pelos exemplos iniciais. Exporte antes se quiser preservá-los.','confirm-reset');
 if(a==='confirm-reset'){state=initialState();room='all';camera=null;close();mutate({ok:true,message:'Demonstração restaurada.'});}
 if(a==='clear-chat')confirm('Limpar conversa?','As mensagens do assistente serão removidas deste navegador. O histórico de ações será preservado.','confirm-clear-chat');
 if(a==='confirm-clear-chat'){state.messages=[];close();mutate({ok:true,message:'Conversa limpa.'});}
 if(a==='export-energy'){const rows=[['Dispositivo','Ambiente','Potência (W)','Uso (h/dia)','kWh/mês','Custo estimado (R$)'],...state.devices.filter(d=>d.type!=='curtain').map(d=>[d.name,roomName(d.room),d.watts,d.hours,fmt(d.watts*d.hours*.03,2),fmt(d.watts*d.hours*.03*state.settings.tariff,2)])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/^[\s]*[=+@-]/,"' $&").replaceAll('"','""')+'"').join(';')).join('\r\n');download('JM_HOME_Projecao_Energia.csv','\uFEFF'+csv,'text/csv;charset=utf-8');}
 if(a==='integration'){const details={ha:['Home Assistant','Servidor Home Assistant, inventário de entidades e um backend que proteja as credenciais. O adaptador deverá ler estados confirmados, enviar serviços autorizados e sinalizar indisponibilidade.'],mqtt:['MQTT / ESP32','Broker MQTT com TLS e autenticação, firmware dos ESP32 e contrato de tópicos para comandos, estado, telemetria e disponibilidade. Um backend deverá validar comandos e confirmar o retorno do dispositivo.'],tuya:['Tuya / Smart Life','Conta e projeto compatíveis com a API oficial, região correta, dispositivos vinculados e permissões necessárias. Compatibilidade e custos precisam ser verificados antes da integração.'],meter:['Medição de energia','Modelo do medidor, grandezas disponíveis, unidades, protocolo e intervalo de leitura. O backend precisará armazenar séries temporais e distinguir falta de dados de consumo zero.']};const [name,detail]=details[id];modal(name,`<span class="pill subtle">INTEGRAÇÃO A IMPLEMENTAR</span><p class="integration-detail">${detail}</p><div class="notice">${I('shield')} Não insira tokens ou senhas no código do navegador.</div><div class="form-actions"><button class="btn secondary" data-act="close-modal">Entendido</button></div>`);}
 if(a==='voice'){const Rec=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Rec){toast('Reconhecimento de voz não disponível. Digite o comando.','warning');return;}modal('Ditado de voz',`<p class="modal-sub">O navegador solicitará acesso ao microfone e poderá enviar o áudio ao seu serviço de reconhecimento. O texto será mostrado para revisão antes de você enviar o comando.</p><button class="btn primary" data-act="start-voice">${I('mic')} Iniciar ditado</button>`);}
 if(a==='start-voice'){close();const Rec=window.SpeechRecognition||window.webkitSpeechRecognition;const rec=new Rec();rec.lang='pt-BR';rec.interimResults=false;rec.maxAlternatives=1;rec.onresult=e=>{const input=$('input[name="command"]');if(input){input.value=e.results[0][0].transcript;input.focus();toast('Texto reconhecido. Revise e envie o comando.');}};rec.onerror=()=>toast('Não foi possível reconhecer a fala. Digite o comando.','warning');try{rec.start();toast('Ouvindo… Fale seu comando.');}catch{toast('Microfone indisponível.','warning');}}
});
document.addEventListener('input',e=>{const t=e.target;if(t.matches('input[type="range"]')){const out=t.closest('label,.range-wrap')?.querySelector('output');if(out)out.textContent=t.value+(t.dataset.control?'%':'');}if(t.id==='device-search'){search=t.value;const start=t.selectionStart;const grid=$('#device-grid');const list=state.devices.filter(d=>(room==='all'||room===d.room)&&(typeFilter==='all'||typeFilter===d.type)&&norm(`${d.name} ${roomName(d.room)}`).includes(norm(search)));grid.innerHTML=list.map(deviceCard).join('')||'<div class="empty">Nenhum dispositivo encontrado.</div>';$('.filter-row>span').textContent=`${list.length} dispositivo(s)`;}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.control){mutate(setDevice(state,t.dataset.id,{[t.dataset.control]:Number(t.value)}));}if(t.dataset.sensor){state.sensors[t.dataset.sensor]=Number(t.value);const results=evaluateRules(state);save();render();toast(results.length?results.map(r=>r.message).join(' '):'Sensor simulado atualizado.');}if(t.id==='type-filter'){typeFilter=t.value;render();}if(t.id==='rule-kind'){$('#rule-time').hidden=t.value!=='time';$('#rule-sensor').hidden=t.value!=='sensor';}if(t.name==='type'&&t.closest('[data-form="device"]')){t.form.elements.watts.value=TYPES[t.value].watts;}
 if(t.dataset.energy){if(!t.checkValidity()){t.reportValidity();return;}const d=state.devices.find(d=>d.id===t.dataset.id);d[t.dataset.energy]=Number(t.value);save();render();}
 if(t.id==='import-file'){const file=t.files[0];t.value='';if(!file)return;if(file.size>1_000_000){toast('Use um arquivo JSON com até 1 MB.','warning');return;}try{pendingImport=cleanState(JSON.parse(await file.text()));confirm('Importar configuração?',`O arquivo contém ${pendingImport.devices.length} dispositivos, ${pendingImport.scenes.length} cenas e ${pendingImport.rules.length} rotinas. Substituir a configuração atual?`,'confirm-import');}catch(err){pendingImport=null;toast(err.message==='Unexpected end of JSON input'?'JSON inválido.':err.message,'warning');}}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const f=new FormData(form),kind=form.dataset.form,id=form.dataset.id;const val=k=>String(f.get(k)??'').trim();
 if(kind==='chat'){const text=val('command');if(text)command(text);return;}
 if(kind==='settings'){if(!val('home')||!val('owner')){toast('Preencha os nomes.','warning');return;}Object.assign(state.settings,{home:val('home'),owner:val('owner'),voice:f.has('voice')});mutate({ok:true,message:'Preferências salvas.'});return;}
 if(kind==='energy'){state.settings.tariff=Number(f.get('tariff'));state.settings.budget=Number(f.get('budget'));mutate({ok:true,message:'Cenário energético atualizado.'});return;}
 if(kind==='device'){if(!val('name'))return;const d=state.devices.find(d=>d.id===id);const data={name:val('name'),room:val('room'),watts:Number(f.get('watts')),hours:Number(f.get('hours')),online:f.has('online')};if(d)Object.assign(d,data);else state.devices.push({...data,id:uid(),type:val('type'),on:false,level:80,temp:23});log(state,`${data.name}: configuração salva.`,'Dispositivos');close();mutate({ok:true,message:'Dispositivo salvo.'});return;}
 if(kind==='scene'){if(!val('name'))return;const actions=[...form.querySelectorAll('.action-editor')].filter(row=>row.querySelector('[name="include"]').checked).map(row=>{const d=state.devices.find(d=>d.id===row.dataset.device),on=row.querySelector('[name="on"]').checked,value=row.querySelector('[name="value"]')?.value;return{device:d.id,on,...(on&&value!==undefined?d.type==='ac'?{temp:Number(value)}:{level:Number(value)}:d.type==='curtain'?{level:0}:{})};});if(!actions.length){toast('Selecione ao menos um dispositivo.','warning');return;}const c={id:id||uid(),name:val('name'),description:val('description'),icon:val('icon'),color:'purple',actions};const i=state.scenes.findIndex(c=>c.id===id);i>=0?state.scenes.splice(i,1,c):state.scenes.push(c);close();mutate({ok:true,message:'Cena salva e pronta para ativar.'});return;}
 if(kind==='rule'){if(!val('name'))return;const r={id:id||uid(),name:val('name'),kind:val('kind'),time:val('time'),sensor:val('sensor'),operator:val('operator'),threshold:Number(f.get('threshold')),scene:val('scene'),enabled:f.has('enabled'),lastRun:'',latched:false};const i=state.rules.findIndex(r=>r.id===id);i>=0?state.rules.splice(i,1,r):state.rules.push(r);close();mutate({ok:true,message:'Rotina salva.'});}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
setInterval(()=>{if(document.hidden)return;const results=evaluateRules(state);if(results.length){save();render();toast(results.map(r=>r.message).join(' '));}},1000);
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=cleanState(JSON.parse(e.newValue));render();toast('Configuração atualizada em outra aba.');}catch{}}});
render();if(!storageOK)toast('Não foi possível restaurar os dados locais. A demonstração foi carregada.','warning');
